from machine import Pin
import framebuf


class Matrix8x8(framebuf.FrameBuffer):
    # mcauser-style driver for chained 8x8 modules (FC-16).
    def __init__(self, spi, cs, num):
        self.spi = spi
        self.cs = Pin(cs, Pin.OUT, value=1)
        self.num = num
        self.buffer = bytearray(8 * num)
        super().__init__(self.buffer, 8 * num, 8, framebuf.MONO_HLSB)
        for c, d in ((0x0F, 0), (0x0C, 0), (0x0B, 7), (0x09, 0), (0x0A, 4), (0x0C, 1)):
            self._write(c, d)

    def _write(self, c, d):
        self.cs(0)
        for m in range(self.num):
            self.spi.write(bytearray([c, d]))
        self.cs(1)

    def show(self):
        for y in range(8):
            self.cs(0)
            for m in range(self.num):
                self.spi.write(bytearray([1 + y, self.buffer[(y * self.num) + m]]))
            self.cs(1)
